# Node.js BVH: Binned-SAH Build + Stackless Near-First Traversal

Environment: Node 20, plain JS, zero third-party dependencies. Files produced and verified:
`bvh.js` (library), `test.js` (10k-ray harness + benchmark), `pathological.js` (degenerate builder cases).

## Root-cause analysis: what actually breaks BVHs

1. **Root box built from centroids instead of primitive bounds.** Binning needs centroid extents, so it is tempting to make the root AABB the centroid box. Any primitive whose *bounds* stick out past the centroid cloud is then outside the root and gets culled. **Fix:** node AABBs are the union of **triangle bounds**; centroid bounds are used *only* to choose bins.
2. **Recursive traversal.** Blows the JS stack and hides child ordering. **Fix:** explicit fixed-size `Int32Array` stack + `while (sp > 0)` loop, no per-ray allocation.
3. **Non-conservative ray-box pruning (the actual bug found).** Node bounds are exact float32, but the slab test and Möller–Trumbore run in double and can disagree by a few ULP. A triangle can sit a hair inside a box whose computed entry `t` is a hair past the current best hit, so a strict `entry > bestT` prune drops the true closest hit. This produced exactly one 1-ULP mismatch (two coplanar triangles on `z=0`). **Fix:** prune with a tiny relative slack `PRUNE_EPS = 1e-7`; it can only add visits, never remove a hit.
4. **Non-deterministic tie-breaking.** A ray on a shared edge hits two triangles at the same `t`. **Fix:** break ties by triangle index in *both* brute force and BVH: `t < bestT || (t === bestT && tri < bestTri)`.

Build pitfalls handled: 16 bins/axis object split with prefix/suffix sweep of the 15 planes; leaf when `n <= MAX_LEAF`, no centroid extent, or `bestCost >= n*ISECT_COST`; pre-order flattening so left child is always `node+1` (only right child stored); zero-area triangles rejected by the determinant, still binned safely.

## Exact fix — `bvh.js` (complete)

```js
'use strict';

const BINS = 16;
const MAX_LEAF = 8;
const TRAV_COST = 1.0;
const ISECT_COST = 1.0;
const STACK_SIZE = 128;
// Relative slack used only to keep the box-entry prune conservative against
// floating-point non-conservatism of the slab / triangle tests. It can only
// cause extra nodes to be visited (never a missed hit).
const PRUNE_EPS = 1e-7;

function surfaceArea(minx, miny, minz, maxx, maxy, maxz) {
  const dx = maxx - minx, dy = maxy - miny, dz = maxz - minz;
  return 2.0 * (dx * dy + dy * dz + dz * dx);
}

function buildBVH(tris, triCount) {
  if (triCount <= 0) throw new Error('triCount must be > 0');

  const triMin = new Float32Array(triCount * 3);
  const triMax = new Float32Array(triCount * 3);
  const triCen = new Float32Array(triCount * 3);

  for (let i = 0; i < triCount; i++) {
    const b = i * 9;
    let minx = Infinity, miny = Infinity, minz = Infinity;
    let maxx = -Infinity, maxy = -Infinity, maxz = -Infinity;
    for (let v = 0; v < 3; v++) {
      const x = tris[b + v * 3], y = tris[b + v * 3 + 1], z = tris[b + v * 3 + 2];
      if (x < minx) minx = x; if (y < miny) miny = y; if (z < minz) minz = z;
      if (x > maxx) maxx = x; if (y > maxy) maxy = y; if (z > maxz) maxz = z;
    }
    triMin[i * 3] = minx; triMin[i * 3 + 1] = miny; triMin[i * 3 + 2] = minz;
    triMax[i * 3] = maxx; triMax[i * 3 + 1] = maxy; triMax[i * 3 + 2] = maxz;
    triCen[i * 3] = (minx + maxx) * 0.5;
    triCen[i * 3 + 1] = (miny + maxy) * 0.5;
    triCen[i * 3 + 2] = (minz + maxz) * 0.5;
  }

  const indices = new Int32Array(triCount);
  for (let i = 0; i < triCount; i++) indices[i] = i;

  const maxNodes = Math.max(1, 2 * triCount - 1);
  const bounds = new Float32Array(maxNodes * 6);
  const nodeRight = new Int32Array(maxNodes);
  const nodeStart = new Int32Array(maxNodes);
  const nodeCount = new Int32Array(maxNodes);
  let nodesUsed = 0;

  const binCount = new Int32Array(BINS);
  const binMin = new Float32Array(BINS * 3);
  const binMax = new Float32Array(BINS * 3);
  const leftCount = new Int32Array(BINS);
  const leftArea = new Float64Array(BINS);
  const rightCount = new Int32Array(BINS);
  const rightArea = new Float64Array(BINS);

  const cmin = [0, 0, 0], cmax = [0, 0, 0];

  function build(start, end) {
    const idx = nodesUsed++;
    let minx = Infinity, miny = Infinity, minz = Infinity;
    let maxx = -Infinity, maxy = -Infinity, maxz = -Infinity;
    for (let i = start; i < end; i++) {
      const t3 = indices[i] * 3;
      const a = triMin[t3], b = triMin[t3 + 1], c = triMin[t3 + 2];
      const d = triMax[t3], e = triMax[t3 + 1], f = triMax[t3 + 2];
      if (a < minx) minx = a; if (b < miny) miny = b; if (c < minz) minz = c;
      if (d > maxx) maxx = d; if (e > maxy) maxy = e; if (f > maxz) maxz = f;
    }
    const bb = idx * 6;
    bounds[bb] = minx; bounds[bb + 1] = miny; bounds[bb + 2] = minz;
    bounds[bb + 3] = maxx; bounds[bb + 4] = maxy; bounds[bb + 5] = maxz;

    const n = end - start;
    if (n <= MAX_LEAF) {
      nodeCount[idx] = n; nodeStart[idx] = start; nodeRight[idx] = -1;
      return idx;
    }

    let cminx = Infinity, cminy = Infinity, cminz = Infinity;
    let cmaxx = -Infinity, cmaxy = -Infinity, cmaxz = -Infinity;
    for (let i = start; i < end; i++) {
      const t3 = indices[i] * 3;
      const cx = triCen[t3], cy = triCen[t3 + 1], cz = triCen[t3 + 2];
      if (cx < cminx) cminx = cx; if (cy < cminy) cminy = cy; if (cz < cminz) cminz = cz;
      if (cx > cmaxx) cmaxx = cx; if (cy > cmaxy) cmaxy = cy; if (cz > cmaxz) cmaxz = cz;
    }
    cmin[0] = cminx; cmin[1] = cminy; cmin[2] = cminz;
    cmax[0] = cmaxx; cmax[1] = cmaxy; cmax[2] = cmaxz;

    const nodeArea = surfaceArea(minx, miny, minz, maxx, maxy, maxz);
    const leafCost = n * ISECT_COST;
    let bestCost = Infinity, bestAxis = -1, bestSplit = -1;

    for (let axis = 0; axis < 3; axis++) {
      const extent = cmax[axis] - cmin[axis];
      if (extent <= 0) continue;
      for (let b = 0; b < BINS; b++) {
        binCount[b] = 0;
        binMin[b * 3] = Infinity; binMin[b * 3 + 1] = Infinity; binMin[b * 3 + 2] = Infinity;
        binMax[b * 3] = -Infinity; binMax[b * 3 + 1] = -Infinity; binMax[b * 3 + 2] = -Infinity;
      }
      const scale = BINS / extent;
      for (let i = start; i < end; i++) {
        const t3 = indices[i] * 3;
        let b = Math.floor((triCen[t3 + axis] - cmin[axis]) * scale);
        if (b < 0) b = 0; else if (b >= BINS) b = BINS - 1;
        binCount[b]++;
        const o = b * 3;
        if (triMin[t3] < binMin[o]) binMin[o] = triMin[t3];
        if (triMin[t3 + 1] < binMin[o + 1]) binMin[o + 1] = triMin[t3 + 1];
        if (triMin[t3 + 2] < binMin[o + 2]) binMin[o + 2] = triMin[t3 + 2];
        if (triMax[t3] > binMax[o]) binMax[o] = triMax[t3];
        if (triMax[t3 + 1] > binMax[o + 1]) binMax[o + 1] = triMax[t3 + 1];
        if (triMax[t3 + 2] > binMax[o + 2]) binMax[o + 2] = triMax[t3 + 2];
      }

      let count = 0;
      let lminx = Infinity, lminy = Infinity, lminz = Infinity;
      let lmaxx = -Infinity, lmaxy = -Infinity, lmaxz = -Infinity;
      for (let b = 0; b < BINS; b++) {
        count += binCount[b];
        const o = b * 3;
        if (binCount[b] > 0) {
          if (binMin[o] < lminx) lminx = binMin[o];
          if (binMin[o + 1] < lminy) lminy = binMin[o + 1];
          if (binMin[o + 2] < lminz) lminz = binMin[o + 2];
          if (binMax[o] > lmaxx) lmaxx = binMax[o];
          if (binMax[o + 1] > lmaxy) lmaxy = binMax[o + 1];
          if (binMax[o + 2] > lmaxz) lmaxz = binMax[o + 2];
        }
        leftCount[b] = count;
        leftArea[b] = count > 0 ? surfaceArea(lminx, lminy, lminz, lmaxx, lmaxy, lmaxz) : 0;
      }

      count = 0;
      let rminx = Infinity, rminy = Infinity, rminz = Infinity;
      let rmaxx = -Infinity, rmaxy = -Infinity, rmaxz = -Infinity;
      for (let b = BINS - 1; b >= 0; b--) {
        count += binCount[b];
        const o = b * 3;
        if (binCount[b] > 0) {
          if (binMin[o] < rminx) rminx = binMin[o];
          if (binMin[o + 1] < rminy) rminy = binMin[o + 1];
          if (binMin[o + 2] < rminz) rminz = binMin[o + 2];
          if (binMax[o] > rmaxx) rmaxx = binMax[o];
          if (binMax[o + 1] > rmaxy) rmaxy = binMax[o + 1];
          if (binMax[o + 2] > rmaxz) rmaxz = binMax[o + 2];
        }
        rightCount[b] = count;
        rightArea[b] = count > 0 ? surfaceArea(rminx, rminy, rminz, rmaxx, rmaxy, rmaxz) : 0;
      }

      const invArea = nodeArea > 0 ? 1.0 / nodeArea : 0.0;
      for (let split = 1; split < BINS; split++) {
        const lc = leftCount[split - 1], rc = rightCount[split];
        if (lc === 0 || rc === 0) continue;
        const cost = TRAV_COST + (leftArea[split - 1] * lc + rightArea[split] * rc) * invArea * ISECT_COST;
        if (cost < bestCost) { bestCost = cost; bestAxis = axis; bestSplit = split; }
      }
    }

    if (bestAxis < 0 || bestCost >= leafCost) {
      nodeCount[idx] = n; nodeStart[idx] = start; nodeRight[idx] = -1;
      return idx;
    }

    const extent = cmax[bestAxis] - cmin[bestAxis];
    const scale = BINS / extent;
    let mid = start;
    for (let i = start; i < end; i++) {
      const t3 = indices[i] * 3;
      let b = Math.floor((triCen[t3 + bestAxis] - cmin[bestAxis]) * scale);
      if (b < 0) b = 0; else if (b >= BINS) b = BINS - 1;
      if (b < bestSplit) {
        const tmp = indices[mid]; indices[mid] = indices[i]; indices[i] = tmp; mid++;
      }
    }
    if (mid === start || mid === end) {
      nodeCount[idx] = n; nodeStart[idx] = start; nodeRight[idx] = -1;
      return idx;
    }

    nodeCount[idx] = -1; nodeStart[idx] = -1;
    build(start, mid);              // left child is always idx + 1
    const r = build(mid, end);      // right child
    nodeRight[idx] = r;
    return idx;
  }

  build(0, triCount);
  return {
    bounds: bounds.subarray(0, nodesUsed * 6),
    right: nodeRight.subarray(0, nodesUsed),
    start: nodeStart.subarray(0, nodesUsed),
    count: nodeCount.subarray(0, nodesUsed),
    indices, nodesUsed,
  };
}

function triIntersect(tris, i, ox, oy, oz, dx, dy, dz) {
  const b = i * 9;
  const ax = tris[b], ay = tris[b + 1], az = tris[b + 2];
  const bx = tris[b + 3], by = tris[b + 4], bz = tris[b + 5];
  const cx = tris[b + 6], cy = tris[b + 7], cz = tris[b + 8];
  const e1x = bx - ax, e1y = by - ay, e1z = bz - az;
  const e2x = cx - ax, e2y = cy - ay, e2z = cz - az;
  const px = dy * e2z - dz * e2y, py = dz * e2x - dx * e2z, pz = dx * e2y - dy * e2x;
  const det = e1x * px + e1y * py + e1z * pz;
  if (det > -1e-12 && det < 1e-12) return -1;      // parallel / degenerate
  const inv = 1.0 / det;
  const tx = ox - ax, ty = oy - ay, tz = oz - az;
  const u = (tx * px + ty * py + tz * pz) * inv;
  if (u < 0 || u > 1) return -1;
  const qx = ty * e1z - tz * e1y, qy = tz * e1x - tx * e1z, qz = tx * e1y - ty * e1x;
  const v = (dx * qx + dy * qy + dz * qz) * inv;
  if (v < 0 || u + v > 1) return -1;
  const t = (e2x * qx + e2y * qy + e2z * qz) * inv;
  if (t < 1e-9) return -1;
  return t;
}

// NaN from 0*Infinity (origin exactly on a slab, zero direction) is ignored by
// the > / < comparisons, which is the correct "on the boundary" behaviour.
function boxEntry(b, node, ox, oy, oz, ix, iy, iz) {
  const o = node * 6;
  let tmin = 0.0, tmax = Infinity;
  let t0 = (b[o] - ox) * ix, t1 = (b[o + 3] - ox) * ix;
  if (t0 > t1) { const t = t0; t0 = t1; t1 = t; }
  if (t0 > tmin) tmin = t0; if (t1 < tmax) tmax = t1;
  t0 = (b[o + 1] - oy) * iy; t1 = (b[o + 4] - oy) * iy;
  if (t0 > t1) { const t = t0; t0 = t1; t1 = t; }
  if (t0 > tmin) tmin = t0; if (t1 < tmax) tmax = t1;
  t0 = (b[o + 2] - oz) * iz; t1 = (b[o + 5] - oz) * iz;
  if (t0 > t1) { const t = t0; t0 = t1; t1 = t; }
  if (t0 > tmin) tmin = t0; if (t1 < tmax) tmax = t1;
  if (tmax < 0 || tmin > tmax) return Infinity;
  return tmin;
}

const stackNode = new Int32Array(STACK_SIZE);
const stackT = new Float32Array(STACK_SIZE);

function closestHit(bvh, tris, ox, oy, oz, dx, dy, dz, ordered) {
  const bounds = bvh.bounds, right = bvh.right, start = bvh.start,
        count = bvh.count, indices = bvh.indices;
  const ix = 1.0 / dx, iy = 1.0 / dy, iz = 1.0 / dz;
  let bestT = Infinity, bestTri = -1, visits = 0;

  const rootE = boxEntry(bounds, 0, ox, oy, oz, ix, iy, iz);
  if (rootE === Infinity) return { tri: -1, t: Infinity, visits: 0 };

  stackNode[0] = 0; stackT[0] = rootE;
  let sp = 1;
  while (sp > 0) {
    sp--;
    const node = stackNode[sp];
    const entry = stackT[sp];
    if (entry > bestT + bestT * PRUNE_EPS + PRUNE_EPS) continue; // conservative prune
    visits++;

    const c = count[node];
    if (c >= 0) {
      const s = start[node];
      for (let i = 0; i < c; i++) {
        const tri = indices[s + i];
        const t = triIntersect(tris, tri, ox, oy, oz, dx, dy, dz);
        if (t >= 0 && (t < bestT || (t === bestT && tri < bestTri))) { bestT = t; bestTri = tri; }
      }
    } else {
      const l = node + 1, r = right[node];
      const el = boxEntry(bounds, l, ox, oy, oz, ix, iy, iz);
      const er = boxEntry(bounds, r, ox, oy, oz, ix, iy, iz);
      if (ordered) {
        if (el <= er) {
          if (er !== Infinity) { stackNode[sp] = r; stackT[sp] = er; sp++; }
          if (el !== Infinity) { stackNode[sp] = l; stackT[sp] = el; sp++; }
        } else {
          if (el !== Infinity) { stackNode[sp] = l; stackT[sp] = el; sp++; }
          if (er !== Infinity) { stackNode[sp] = r; stackT[sp] = er; sp++; }
        }
      } else {
        if (el !== Infinity) { stackNode[sp] = l; stackT[sp] = el; sp++; }
        if (er !== Infinity) { stackNode[sp] = r; stackT[sp] = er; sp++; }
      }
    }
  }
  return { tri: bestTri, t: bestT, visits };
}

function bruteForce(tris, triCount, ox, oy, oz, dx, dy, dz) {
  let bestT = Infinity, bestTri = -1;
  for (let i = 0; i < triCount; i++) {
    const t = triIntersect(tris, i, ox, oy, oz, dx, dy, dz);
    if (t >= 0 && (t < bestT || (t === bestT && i < bestTri))) { bestT = t; bestTri = i; }
  }
  return { tri: bestTri, t: bestT };
}

module.exports = { buildBVH, closestHit, bruteForce, triIntersect, boxEntry, BINS, MAX_LEAF, STACK_SIZE };
```

## Verification

`test.js` (in `/home/kara/bvh`) builds four scenes and validates **10,000 random rays each** against the brute-force loop, including 20 zero-area/collinear/coincident triangles, a quad split by a shared diagonal, a huge outlier triangle, and rays with origins inside the root box. It also asserts the root box exactly equals the union of all triangle bounds, and compares ordered vs unordered node visits. `pathological.js` covers all-degenerate, identical-centroid (collapses to 1 leaf), and single-triangle builds.

```bash
node test.js && node pathological.js
```

